1	import { afterEach, describe, expect, it } from 'vitest';
2	import type { ChatMessage } from '@dailies/agent';
3	import type { Claim, IngestArtifact, Scene } from '@dailies/core';
4	import { groundStage } from '../../src/stages/ground';
5	import { cleanup, harness, json, promptText, scriptArtifact, session, twoSessions, writerReply, LIE, PASSED_RUN, SHA_A, type MockRequest } from './fixture';
6	
7	afterEach(cleanup);
8	
9	const userText = (req: MockRequest) => String(req.messages.find((m) => m.role === 'user')?.content ?? '');
10	
11	/**
12	 * A judge that finds a sentence entailed unless `rejects` matches the request, and a writer whose rewrites come
13	 * from `rewrites` in order. A rewrite asked for beyond the list fails the test.
14	 */
15	function models(o: { rejects?: (text: string) => boolean; rewrites?: unknown[] } = {}): (req: MockRequest) => ChatMessage {
16	  const rewrites = [...(o.rewrites ?? [])];
17	  return (req) => {
18	    if (req.role === 'judge') return json({ entailed: !(o.rejects?.(userText(req)) ?? false) });
19	    if (req.role === 'writer') {
20	      if (rewrites.length === 0) throw new Error('no rewrite was expected here');
21	      return json(rewrites.shift());
22	    }
23	    throw new Error(`unexpected role ${req.role}`);
24	  };
25	}
26	
27	async function ground(o: { reply?: unknown; claims?: Claim[]; ingest?: IngestArtifact; rejects?: (text: string) => boolean; rewrites?: unknown[] } = {}) {
28	  const ingest = o.ingest ?? twoSessions();
29	  const script = await scriptArtifact({ reply: o.reply, claims: o.claims, ingest });
30	  const h = harness({ artifacts: { ingest, script }, reply: models(o) });
31	  const result = await groundStage(h.deps).run(h.ctx());
32	  const asked = (role: string) => h.calls.filter((c) => c.role === role);
33	  return { h, script, result, artifact: result.artifact, scenes: result.artifact.storyboard.scenes, asked };
34	}
35	
36	const types = (scenes: Scene[]) => scenes.map((s) => s.type);
37	const lineIds = (scenes: Scene[]) => scenes.flatMap((s) => s.lines.map((l) => l.id));
38	const lineOf = (scenes: Scene[], id: string) => scenes.flatMap((s) => s.lines).find((l) => l.id === id);
39	/** The writer's reply with the lines of one scene replaced. */
40	const withLines = (sceneIndex: number, lines: unknown[]) => ({ scenes: writerReply().scenes.map((scene, n) => (n === sceneIndex ? { ...scene, lines } : scene)) });
41	
42	describe('ground stage', () => {
43	  it('ground keeps every line that resolves and that the judge finds entailed', async () => {
44	    const { script, result, artifact, asked } = await ground();
45	
46	    expect(artifact.storyboard).toEqual(script.storyboard);
47	    expect(artifact.dropped).toEqual([]);
48	    expect(artifact.kept).toBe(7);
49	    expect(result.loopBackTo).toBeUndefined();
50	    expect(asked('judge')).toHaveLength(5);   // the 5 written lines, not the 2 lines of the flag
51	    expect(asked('writer')).toHaveLength(0);
52	  });
53	
54	  it('ground gives the judge the sentence and the text of its evidence', async () => {
55	    const { asked } = await ground();
56	
57	    const told = asked('judge').map((c) => promptText(c.messages));
58	    expect(told[0]).toContain('The session opened with a request to retry failed jobs.');
59	    expect(told[0]).toContain('The queue drops jobs when the worker restarts.');
60	    expect(told[1]).toContain('return this.run(job);');                       // the patch the diff reference points at
61	    for (const line of PASSED_RUN.split('\n')) expect(told[3]).toContain(`| ${line}`);
62	    expect(told[4]).toContain('sessions.count = 2');
63	    expect(told[4]).toContain('commits.count = 2');
64	    expect(told[0]).toMatch(/"entailed"/);
65	    for (const part of ['problem', 'key decisions', 'implementation', 'recorded validation']) expect(told[0]).toContain(part);
66	  });
67	
68	  it('ground drops a line after two failed rewrites and removes the empty scene', async () => {
69	    const { artifact, scenes, asked, result } = await ground({
70	      rejects: (text) => /retry (lives|sits|is somewhere)/.test(text),
71	      rewrites: [{ text: 'The retry sits in the run method.' }, { text: 'The retry is somewhere in the queue.' }],
72	    });
73	
74	    expect(artifact.dropped).toEqual([{ lineId: 'l2', reasons: ['not entailed by its evidence'] }]);
75	    expect(types(scenes)).toEqual(['title', 'prompt', 'terminal', 'flag', 'terminal', 'stats', 'end']);   // the diff scene had only that line
76	    expect(lineIds(scenes)).not.toContain('l2');
77	    expect(artifact.kept).toBe(6);
78	    expect(result.loopBackTo).toBeUndefined();
79	
80	    expect(asked('writer')).toHaveLength(2);
81	    const first = promptText(asked('writer')[0]!.messages);
82	    expect(first).toContain('The retry lives in the run method of the queue.');
