84	    expect(first).toContain('return this.run(job);');
85	    expect(promptText(asked('writer')[1]!.messages)).toContain('The retry sits in the run method.');
86	    for (const part of ['problem', 'key decisions', 'implementation', 'recorded validation', 'exactly as']) expect(first).toContain(part);
87	    expect(asked('judge')).toHaveLength(7);   // 5 lines, and the 2 rewrites of the one that failed
88	  });
89	
90	  it('ground keeps a rewritten line once it passes, under the same id', async () => {
91	    const { artifact, scenes, asked } = await ground({
92	      rejects: (text) => text.includes('on the retry count'),
93	      rewrites: [{ text: 'The queue test run failed.' }],
94	    });
95	
96	    expect(artifact.dropped).toEqual([]);
97	    expect(lineOf(scenes, 'l3')).toEqual({ id: 'l3', text: 'The queue test run failed.', evidence: [{ type: 'entry', entryId: 's1:5' }] });
98	    expect(asked('writer')).toHaveLength(1);
99	    expect(artifact.kept).toBe(7);
100	  });
101	
