103	    const reply = withLines(3, [{ text: 'In the second session all 7 tests passed.', evidence: [{ type: 'entry', entryId: 's2:5' }] }]);
104	
105	    const { artifact, scenes, asked } = await ground({ reply, rewrites: [{ text: 'In the second session all 3 tests passed.' }] });
106	
107	    expect(artifact.dropped).toEqual([]);
108	    expect(lineOf(scenes, 'l4')!.text).toBe('In the second session all 3 tests passed.');
109	    expect(promptText(asked('writer')[0]!.messages)).toContain('number not grounded in evidence: 7');
110	    expect(asked('judge').some((c) => userText(c).includes('all 7 tests'))).toBe(false);
111	  });
112	
113	  it('ground sends a line that breaks the style lint to the writer', async () => {
114	    const reply = withLines(0, [{ text: 'The session opened with a robust request — to retry failed jobs!', evidence: [{ type: 'entry', entryId: 's1:0' }] }]);
115	
116	    const { scenes, asked } = await ground({ reply, rewrites: [{ text: 'The session opened with a request to retry failed jobs.' }] });
117	
118	    const told = promptText(asked('writer')[0]!.messages);
119	    expect(told).toContain('banned phrase: robust');
120	    expect(told).toContain('contains an em dash or an exclamation mark');
121	    expect(lineOf(scenes, 'l1')!.text).toBe('The session opened with a request to retry failed jobs.');
122	  });
123	
124	  it('ground drops a line whose evidence does not resolve when no rewrite fixes it', async () => {
125	    const reply = withLines(0, [{ text: 'The session opened with a request to retry failed jobs.', evidence: [{ type: 'entry', entryId: 's9:99' }] }]);
126	
127	    const { artifact, scenes, asked } = await ground({ reply, rewrites: [{ text: 'A request opened the session.' }, { text: 'The session opened with a request.' }] });
128	
129	    expect(artifact.dropped).toEqual([{ lineId: 'l1', reasons: ['unknown entry: s9:99'] }]);
130	    expect(types(scenes)).toEqual(['title', 'diff', 'terminal', 'flag', 'terminal', 'stats', 'end']);
131	    expect(promptText(asked('writer')[0]!.messages)).toContain('does not resolve');
